<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div class="content"><div class="row"><div class="col-md-8"><h4><?= html_escape($title); ?></h4><div class="panel_s"><div class="panel-body"><form method="post" action="<?= admin_url('affiliate/categories'); ?>" class="form-inline"><input class="form-control" required name="name" placeholder="New category name"><button class="btn btn-primary">Add category</button></form><hr><table class="table"><thead><tr><th>Name</th><th></th></tr></thead><tbody><?php foreach ($categories as $category): ?><tr><td><form method="post" action="<?= admin_url('affiliate/categories'); ?>" class="form-inline"><input type="hidden" name="id" value="<?= (int)$category->id; ?>"><input class="form-control" required name="name" value="<?= html_escape($category->name); ?>"><button class="btn btn-default btn-xs">Save</button></form></td><td class="text-right"><a class="btn btn-danger btn-xs" href="<?= admin_url('affiliate/delete_category/'.$category->id); ?>" onclick="return confirm('Delete this category? Products will become uncategorized.');">Delete</a></td></tr><?php endforeach; ?></tbody></table></div></div></div></div></div><?php init_tail(); ?>
